import{_ as c,l,o as a,c as t,v as o,p as i,x as d,d as s,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"FSDP","description":"","frontmatter":{"title":"FSDP","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fsdp.md","filePath":"llm/fsdp.md","lastUpdated":1789023840000}'),h={name:"llm/fsdp.md"};function D(_,e,A,P,S,u){const r=l("Mermaid");return a(),t("div",null,[e[1]||(e[1]=o('<h1 id="fsdp" tabindex="-1">FSDP <a class="header-anchor" href="#fsdp" aria-label="Permalink to &quot;FSDP&quot;">​</a></h1><div class="epigraph"><p>把参数、梯度和优化器状态按包装单元切到数据并行组上，用时 All-Gather，用完再切回去——这是 PyTorch 里与 ZeRO-3 最近的那条官方路径。</p><footer>—— PyTorch 文档：FullyShardedDataParallel / ShardingStrategy</footer></div><p>DeepSpeed 用 ZeRO 档位说话，PyTorch 用 <strong>Fully Sharded Data Parallel (FSDP)</strong> 说话。切的对象是同一张表：参数、梯度、优化器状态；通信仍是 All-Gather 与 Reduce-Scatter。差别在接口、包装粒度、以及混合精度、预取、混合分片这些旋钮如何暴露。本篇按 PyTorch 稳定文档写 FSDP 的策略与包装，不重写 <a href="/llm/zero-stages">ZeRO 三档的内存公式</a>，也不把某一版 nightly 的未定 API 当成规范。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDP 每张卡复制完整参数、梯度与优化器状态，模型稍大就 OOM。用户若跳到 DeepSpeed，要换启动器、换配置文件、有时换优化器封装。PyTorch 需要一条仍在 <code>nn.Module</code> 上工作、集体通信走 <code>torch.distributed</code> 的分片数据并行：训练循环看起来像 DDP，内存语义接近 ZeRO。</p><p>问题立刻变成三个工程选择。第一，切多深：只切梯度与优化器，还是连参数也切。第二，All-Gather 的单位多大：整网一次，还是每个 Transformer 块一次。第三，多机时要不要在节点内切、节点间复制，以免跨机 All-Gather 把以太网打满。这些不是三套算法，是同一套分片状态机上的策略枚举。</p><h3 id="策略名与-zero-档位对齐" tabindex="-1">策略名与 ZeRO 档位对齐 <a class="header-anchor" href="#策略名与-zero-档位对齐" aria-label="Permalink to &quot;策略名与 ZeRO 档位对齐&quot;">​</a></h3><p>文档中的 <code>ShardingStrategy</code>：</p><ul><li><code>FULL_SHARD</code>（默认）：参数、梯度、优化器状态都分片。前向计算前 All-Gather 出完整参数，前向后重新分片；反传前再 Gather，反传后 Reduce-Scatter 梯度。各 rank 只更新自己的优化器片。对应最深的 ZeRO-3。</li><li><code>SHARD_GRAD_OP</code>：计算期间参数保持完整，计算结束后再分片；梯度与优化器状态分片。少一次前向后的 reshard，省通信、费显存。接近 ZeRO-2。</li><li><code>NO_SHARD</code>：相当于 DDP，用来当对照基线。</li><li><code>HYBRID_SHARD</code>：在一个「单位」（通常是节点内 GPU）上做 <code>FULL_SHARD</code>，单位之间复制。节点内走 NVLink 做深切，节点间像 DDP 一样 All-Reduce 梯度语义。多机上常见折中。</li></ul><p><span class="marginnote"><code>use_orig_params=True</code> 时，<code>SHARD_GRAD_OP</code> 在前向之后暴露的是未分片参数，行为与 <code>FULL_SHARD</code> 不同。调试时用 <code>summon_full_params</code>（需要梯度则 <code>with_grads=True</code>）查看，不要假设 <code>named_parameters()</code> 在两种策略下指向同一布局。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FSDP 把模块树切成若干 <strong>wrapping unit</strong>。每个 unit 是一次 All-Gather / Reduce-Scatter 的粒度。<code>auto_wrap_policy</code> 常用 <code>transformer_auto_wrap_policy</code>，把 <code>LlamaDecoderLayer</code> 一类块包成独立 FSDP 实例；也可用按参数量阈值的 size-based 策略。整模型一个 unit：通信次数少，峰值高（一次取齐太多权重）。每层一个 unit：峰值低，NCCL 启动次数随层数涨。块级是常见折中，与 ZeRO-3 的 wrap 是同一旋钮，只是 API 名字不同。</p><p>混合精度由 <code>MixedPrecision</code> 指定参数、梯度、缓冲的 dtype，与「计算用 BF16、主状态用 FP32」的常见配方对齐，但是 FSDP 自己的模块，不必绑 Apex。<code>backward_prefetch</code> 默认 <code>BACKWARD_PRE</code>：反传当前 unit 时预取下一 unit 的参数，用显存换隐藏延迟。<code>limit_all_gathers</code> 限制同时在飞的 Gather，防止预取把峰值顶破。<code>cpu_offload=CPUOffload(offload_params=True)</code> 把参数卸到主机，墙钟通常明显变慢，语义上也离开「只卸优化器」的 ZeRO-Offload 合同。</p>',13)),(a(),i(p,null,{default:d(()=>[n(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22wrap%20%E6%88%90%20FSDP%20unit%22%5D%20--%3E%20AG%5B%22All-Gather%20%E5%8F%82%E6%95%B0%22%5D%0A%20%20AG%20--%3E%20F%5B%22unit%20%E5%89%8D%E5%90%91%22%5D%0A%20%20F%20--%3E%20RS1%5B%22FULL_SHARD%3A%20%E7%AB%8B%E5%8D%B3%20reshard%22%5D%0A%20%20F%20--%3E%20KEEP%5B%22SHARD_GRAD_OP%3A%20%E8%AE%A1%E7%AE%97%E6%9C%9F%E4%BF%9D%E6%8C%81%E5%AE%8C%E6%95%B4%22%5D%0A%20%20RS1%20--%3E%20BW%5B%22%E5%8F%8D%E4%BC%A0%E5%89%8D%E5%86%8D%20Gather%22%5D%0A%20%20KEEP%20--%3E%20BW%0A%20%20BW%20--%3E%20RSG%5B%22Reduce-Scatter%20%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20RSG%20--%3E%20OPT%5B%22%E5%90%84%20rank%20%E6%9B%B4%E6%96%B0%E6%9C%AC%E5%9C%B0%E4%BC%98%E5%8C%96%E5%99%A8%E7%89%87%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="从-fsdp1-到可组合的-fully-shard" tabindex="-1">从 FSDP1 到可组合的 fully_shard <a class="header-anchor" href="#从-fsdp1-到可组合的-fully-shard" aria-label="Permalink to &quot;从 FSDP1 到可组合的 fully_shard&quot;">​</a></h3><p>第一代 API 是 <code>FullyShardedDataParallel</code> 包装整个模块。PyTorch 后续引入基于 DTensor 的 <strong>FSDP2</strong>（<code>torch.distributed.fsdp.fully_shard</code> 一类可组合接口）：分片状态是张量上的布局，而不是一个巨大的 wrapper 对象，便于与 <code>torch.compile</code>、流水线、其他并行维组合。迁移时不要假设两套默认策略、预取与 <code>use_orig_params</code> 完全同构；以你锁定的版本文档为准。本篇以稳定文档里仍在的 <code>ShardingStrategy</code> 语义为准，不把某一 commit 的默认值写成永恒定律。</p><p><code>device_mesh</code> 把混合分片从「隐式按节点」变成显式网格：哪一维是 shard，哪一维是 replicate。这与 JAX 的 mesh 是同一类思想，只是运行时仍是 NCCL 而不是 XLA 分区器。检查点：分片检查点按 rank 写片；要导出完整权重，需 <code>summon_full_params</code> 或专门的聚合作业，峰值内存会回到「几乎一份完整模型」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>状态机比公式重要。对每个 unit，<code>FULL_SHARD</code> 在时间轴上交替「完整」与「分片」：完整只覆盖该 unit 的计算窗口。窗口外 GPU 上是 \\(1/N\\) 的参数。峰值 ≈ 分片常驻 + 当前 unit 完整参数 + 激活 + 预取的下一 unit。包装越粗，窗口越大。这就是为什么只报「FSDP 省 \\(N\\) 倍」会骗人：省的是常驻，不是峰值。</p><p><code>HYBRID_SHARD</code> 的机制是缩小 All-Gather 的进程组。组内 \\(n_{\\mathrm{local}}\\) 张卡做深切，组间复制一份逻辑模型。跨机不再每层 Gather 整网参数，只在副本之间同步梯度。节点内 NVLink 吃得起 ZeRO-3 的次数，以太网往往吃不起。代价是每台机器仍要放下「一份完整模型 / \\(n_{\\mathrm{local}}\\)」，机器太少或单机卡太少时混合分片省不出那一档。</p><p><span class="marginnote">FSDP 的通信次数随 unit 数线性涨，体积每层仍与该 unit 参数量同阶。深而窄、wrap 很细、跨机 <code>FULL_SHARD</code>，延迟项会压过省显存换来的更大微批。选策略先看拓扑：节点内 <code>FULL_SHARD</code>，跨机优先 <code>HYBRID_SHARD</code> 或 <code>SHARD_GRAD_OP</code>，而不是看模型参数口号。</span></p><h3 id="与-deepspeed-的工程差-而不是数学差" tabindex="-1">与 DeepSpeed 的工程差，而不是数学差 <a class="header-anchor" href="#与-deepspeed-的工程差-而不是数学差" aria-label="Permalink to &quot;与 DeepSpeed 的工程差，而不是数学差&quot;">​</a></h3><p>数学对象几乎相同：分片数据并行。工程差包括：启动器与配置（Python 参数 vs JSON）；优化器是否必须包一层；CPU 卸载默认卸什么；MoE / 流水线的成熟度随生态走；以及检查点格式。写报告应同时写「<code>FULL_SHARD</code> + transformer wrap」和「切了参数 / 梯度 / 状态」，避免「我们用了 FSDP」无法对照「我们用了 ZeRO-3」。不要把 FSDP 当成张量并行：它不切单层矩阵的列，All-Reduce 语义在 DDP 对照里才出现。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在单卡已能 DDP 时默认 <code>FULL_SHARD</code>。不要把自定义缓冲、非 <code>nn.Parameter</code> 的缓存、或被 <code>ignored_modules</code> 漏掉的层当成已分片。不要在 <code>no_sync</code> 梯度累积时忘记：<code>SHARD_GRAD_OP</code> 在 <code>no_sync</code> 内反传后可以不 reshard，峰值行为会变。<code>sync_module_states</code> 用于从 rank0 广播初始权重，初始化在 CPU 上用 <code>param_init_fn</code> 可避免所有卡同时物化完整 FP32。</p><p>与梯度裁剪、全局范数：必须在分片上做正确归约。与 <code>torch.compile</code>：FSDP2 的可组合性是为这个准备的，但图断裂、动态 wrap 仍是常见坑，要用你目标版本的已知限制清单，而不是假设「compile 后 FSDP 免费加速」。</p><p><span class="marginnote">出处以 PyTorch 稳定文档的 <code>FullyShardedDataParallel</code> 与 <code>ShardingStrategy</code> 为准。第三方博客里「FULL 只要 model/N、SHARD_GRAD_OP 只要 45 GB」一类算例依赖具体模型与是否算激活，不能当公式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSDP 是 PyTorch 的分片数据并行：unit 级 All-Gather 参数、Reduce-Scatter 梯度，优化器片本地更新。</li><li><code>FULL_SHARD</code> ≈ ZeRO-3，<code>SHARD_GRAD_OP</code> ≈ ZeRO-2，<code>NO_SHARD</code> ≈ DDP，<code>HYBRID_SHARD</code> 为节点内深切、节点间复制。</li><li>wrap 粒度决定峰值与通信次数；预取、<code>limit_all_gathers</code>、混合精度是同一状态机上的旋钮。</li><li>参数 CPU 卸载与 ZeRO-Offload 默认合同不同；导出完整权重需要专门的聚集。</li><li>跨机优先缩小 Gather 组，而不是无条件全网 <code>FULL_SHARD</code>。</li><li>出处：PyTorch 文档 <em>FullyShardedDataParallel</em>；语义对照见 <a href="/llm/zero-stages">ZeRO 三档</a>。</li></ul>',15))])}const f=c(h,[["render",D]]);export{R as __pageData,f as default};
